export const DEFAULT_POPULAR_REACTIONS: string[] = [
  "👍", "❤️", "😂", "😮", "😢", "🙏",
  "🔥", "😭", "💀", "🤣", "🥰", "😍",
  "🎉", "👀", "💯", "✨", "👏", "🙌",
  "🤔", "🫡", "🫶", "💔", "🤝", "🗿",
];

const RECENT_REACTIONS_STORAGE_KEY = "jatext-recent-reactions-v1";

export function getRecentReactions(): string[] {
  try {
    const raw = localStorage.getItem(RECENT_REACTIONS_STORAGE_KEY);
    if (!raw) return DEFAULT_POPULAR_REACTIONS;
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return DEFAULT_POPULAR_REACTIONS;
    const valid = parsed.filter((item): item is string => typeof item === "string" && item.trim().length > 0);
    const merged = [...valid];
    for (const fallback of DEFAULT_POPULAR_REACTIONS) {
      if (!merged.includes(fallback) && merged.length < 32) {
        merged.push(fallback);
      }
    }
    return merged.slice(0, 32);
  } catch {
    return DEFAULT_POPULAR_REACTIONS;
  }
}

export function recordRecentReaction(emoji: string): void {
  const clean = emoji.trim();
  if (!clean) return;
  try {
    const current = getRecentReactions().filter((item) => item !== clean);
    localStorage.setItem(
      RECENT_REACTIONS_STORAGE_KEY,
      JSON.stringify([clean, ...current].slice(0, 32)),
    );
  } catch {
    // Ignore storage quota errors
  }
}

