let cachedByCategory: Record<Exclude<EmojiCategoryId, "recent">, EmojiEntry[]> | null = null;
let cachedAllEmojis: EmojiEntry[] | null = null;

export function getEmojisByCategory(category: Exclude<EmojiCategoryId, "recent">): EmojiEntry[] {
  if (!cachedByCategory) {
    cachedByCategory = {
      smileys: RAW_EMOJI_DATA.smileys.map(([emoji, keywords]) => ({ emoji, keywords, category: "smileys" })),
      people: RAW_EMOJI_DATA.people.map(([emoji, keywords]) => ({ emoji, keywords, category: "people" })),
      animals: RAW_EMOJI_DATA.animals.map(([emoji, keywords]) => ({ emoji, keywords, category: "animals" })),
      food: RAW_EMOJI_DATA.food.map(([emoji, keywords]) => ({ emoji, keywords, category: "food" })),
      activities: RAW_EMOJI_DATA.activities.map(([emoji, keywords]) => ({ emoji, keywords, category: "activities" })),
      travel: RAW_EMOJI_DATA.travel.map(([emoji, keywords]) => ({ emoji, keywords, category: "travel" })),
      objects: RAW_EMOJI_DATA.objects.map(([emoji, keywords]) => ({ emoji, keywords, category: "objects" })),
      symbols: RAW_EMOJI_DATA.symbols.map(([emoji, keywords]) => ({ emoji, keywords, category: "symbols" })),
      flags: RAW_EMOJI_DATA.flags.map(([emoji, keywords]) => ({ emoji, keywords, category: "flags" })),
    };
  }
  return cachedByCategory[category];
}

export function searchEmojis(query: string): EmojiEntry[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  if (!cachedAllEmojis) {
    cachedAllEmojis = (
      ["smileys", "people", "animals", "food", "activities", "travel", "objects", "symbols", "flags"] as const
    ).flatMap((cat) => getEmojisByCategory(cat));
  }
  const tokens = q.split(/\s+/).filter(Boolean);
  return cachedAllEmojis.filter(
    (entry) =>
      entry.emoji === q ||
      tokens.every((token) => entry.keywords.includes(token)),
  );
}
